-- Distribution OS — consolidated multi-enterprise baseline (Phase 2).
-- GENERATED by packages/db/tools/generate-init.mjs — do not edit by hand.
-- Source: Sri Aparajita live schema (introspected). enterprise_id + RLS baked in.

BEGIN;

CREATE EXTENSION IF NOT EXISTS pgcrypto WITH SCHEMA public;

-- ── RLS helper functions (empty GUC → NULL, so policies fail closed) ───────
CREATE FUNCTION public.app_current_enterprise_id() RETURNS uuid
  LANGUAGE sql STABLE AS $$ SELECT NULLIF(current_setting('app.enterprise_id', true), '')::uuid $$;
CREATE FUNCTION public.app_current_user_id() RETURNS uuid
  LANGUAGE sql STABLE AS $$ SELECT NULLIF(current_setting('app.user_id', true), '')::uuid $$;

-- ── Foundation: enterprises + control-plane + onboarding ────────────────────
CREATE TABLE public.enterprises (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    name text NOT NULL,
    legal_name text NOT NULL,
    gstin text NOT NULL,
    contact_name text NOT NULL,
    contact_phone text NOT NULL,
    contact_email text NOT NULL,
    address_line1 text NOT NULL,
    address_line2 text,
    address_city text NOT NULL,
    address_state text NOT NULL,
    address_pincode text NOT NULL,
    status text DEFAULT 'pending' NOT NULL,
    created_by uuid,
    approved_by uuid,
    approved_at timestamp with time zone,
    rejected_reason text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT enterprises_status_check CHECK (status IN ('pending','active','rejected','suspended'))
);

CREATE TABLE public.platform_owners (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    auth_user_id text NOT NULL,
    name text,
    email text,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE public.enterprise_billing_config (
    enterprise_id uuid NOT NULL,
    model text NOT NULL,
    unit_amount_paisa integer,
    flat_amount_paisa integer,
    gst_rate_bp integer DEFAULT 1800 NOT NULL,
    currency text DEFAULT 'INR' NOT NULL,
    updated_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ebc_model_check CHECK (model IN ('per_seat','flat'))
);

CREATE TABLE public.subscription_invoices (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    enterprise_id uuid NOT NULL,
    charge_id uuid NOT NULL,
    invoice_no text NOT NULL,
    invoice_date date NOT NULL,
    taxable_paisa integer NOT NULL,
    gst_paisa integer NOT NULL,
    total_paisa integer NOT NULL,
