-- ── Roles (tenant isolation without FORCE/BYPASSRLS) ───────────────────────
DO $$
BEGIN
  IF NOT EXISTS (SELECT FROM pg_roles WHERE rolname = 'app_tenant') THEN
    CREATE ROLE app_tenant NOLOGIN;
  END IF;
  IF NOT EXISTS (SELECT FROM pg_roles WHERE rolname = 'app_readonly') THEN
    CREATE ROLE app_readonly NOLOGIN;
  END IF;
  -- let the owner (whoever runs this) SET ROLE into the tenant roles
  EXECUTE format('GRANT app_tenant TO %I', current_user);
  EXECUTE format('GRANT app_readonly TO %I', current_user);
END $$;
GRANT USAGE ON SCHEMA public TO app_tenant, app_readonly;
GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA public TO app_tenant;
GRANT SELECT ON ALL TABLES IN SCHEMA public TO app_readonly;
-- enterprises + control-plane stay owner-only: revoke tenant write, keep read.
REVOKE INSERT, UPDATE, DELETE ON public.enterprises, public.platform_owners,
  public.enterprise_billing_config, public.subscription_invoices FROM app_tenant;
REVOKE ALL ON public.platform_owners FROM app_tenant, app_readonly;

-- ── Row-Level Security: every enterprise-scoped table ──────────────────────
-- ENABLE (not FORCE): the owner role bypasses RLS (control-plane + cockpit);
-- app_tenant obeys it. The app sets `app.enterprise_id` per request via
-- SET LOCAL inside the txn. current_setting(..., true) is NULL when unset →
-- policy fails closed (no rows).
ALTER TABLE public.alerts ENABLE ROW LEVEL SECURITY;
CREATE POLICY enterprise_isolation ON public.alerts
  USING (enterprise_id = public.app_current_enterprise_id())
  WITH CHECK (enterprise_id = public.app_current_enterprise_id());
