-- enterprises: a tenant session reads only its own row (owner manages writes).
ALTER TABLE public.enterprises ENABLE ROW LEVEL SECURITY;
CREATE POLICY enterprise_self ON public.enterprises FOR SELECT
  USING (id = public.app_current_enterprise_id());

-- onboarding_drafts: pre-enterprise; scoped to the signed-up user.
ALTER TABLE public.onboarding_drafts ENABLE ROW LEVEL SECURITY;
CREATE POLICY onboarding_self ON public.onboarding_drafts
  USING (user_id = public.app_current_user_id())
  WITH CHECK (user_id = public.app_current_user_id());

-- platform_owners: owner-only. RLS on, NO policy → tenants see nothing;
-- the owner role (non-forced) manages it.
ALTER TABLE public.platform_owners ENABLE ROW LEVEL SECURITY;

